-- Add PagedAttention, introduced in arXiv 2309.06180. Production chat users looked it
-- up on 2026-10-15/16 and the catalog had no row. The source paper gets the
-- source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'paged-attention',
    'PagedAttention',
    'PagedAttention',
    'PagedAttention is an attention algorithm and KV-cache memory manager for large language model serving, inspired by virtual memory and paging in operating systems. Rather than reserving one contiguous buffer per request for its maximum possible length, it splits each sequence''s key-value cache into fixed-size blocks that can live anywhere in GPU memory. A per-request block table maps logical blocks to physical ones, and the attention kernel gathers keys and values block by block. This removes external fragmentation, limits internal fragmentation to a sequence''s last block, allocates memory on demand, and lets parallel samples, beam-search candidates and requests with a shared prompt prefix share blocks through copy-on-write. Built on PagedAttention, the vLLM serving engine improved throughput by 2–4× at the same latency over FasterTransformer and Orca. The same paging idea is now standard in LLM inference engines and complements kernel-level work such as [Flash Attention](/methods/flash-attention).',
    'PagedAttention, paged attention, Paged Attention, paged KV cache, paged KV-cache',
    (
        SELECT id
        FROM areas
        WHERE name = 'Language'
        LIMIT 1
    ),
    2023,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2309.06180'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Efficient Memory Management for Large Language Model Serving with PagedAttention',
    'https://github.com/vllm-project/vllm',
    NULL,
    '[Efficient Memory Management for Large Language Model Serving with PagedAttention](/paper/2309.06180)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id
FROM methods
WHERE slug = 'paged-attention'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source'
FROM methods
WHERE slug = 'paged-attention'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

-- Citation review 2026-10-16: 15 of the 3084 local papers that Semantic Scholar
-- lists as citing the source name PagedAttention in their title or abstract.
CREATE TEMP TABLE paged_attention_linked_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'paged-attention'
  AND p.is_latest_version
  AND p.id IN (
        22996, -- S-LoRA: Serving Thousands of Concurrent LoRA Adapters
        24539, -- Stateful Large Language Model Serving with Pensieve
        31122, -- vAttention: Dynamic Memory Management for Serving LLMs without PagedAtte
        33015, -- Quest: Query-Aware Sparsity for Efficient Long-Context LLM Inference
        41167, -- Flex Attention: A Programming Model for Generating Optimized Attention K
        57446, -- IceCache: Memory-efficient KV-cache Management for Long-Sequence LLMs
        66876, -- The Anatomy of a Triton Attention Kernel
        68727, -- PagedEviction: Structured Block-wise KV Cache Pruning for Efficient Larg
        74507, -- KVCrush: Key value cache size-reduction using similarity in head-behavio
        83401, -- OSCAR: Offline Spectral Covariance-Aware Rotation for 2-bit KV Cache Qua
        85804, -- NestedFP: High-Performance, Memory-Efficient Dual-Precision Floating Poi
        94410, -- Out of the Memory Barrier: A Highly Memory-Efficient Training System for
        94795, -- ThinKV: Thought-Adaptive KV Cache Compression for Efficient Reasoning Mo
        98427, -- Tangram: Unlocking Non-Uniform KV Cache Compression for Efficient Multi-
        109532 -- FlashPrefill V2: Block-Sparse Prefill Attention for Long-Context LLM Ser
  );

DELETE FROM paper_method_exclusions x
USING paged_attention_linked_papers l
WHERE x.paper_id = l.paper_id AND x.method_id = l.method_id;

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM paged_attention_linked_papers
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT paper_id, method_id, 'reference' FROM paged_attention_linked_papers
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

